// Frontend/src/pages/LoginPage.tsx - Demo Mode (No Firebase)
import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { usersAPI } from '../services/api';

const LoginPage: React.FC = () => {
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [email, setEmail] = useState('');
  const [name, setName] = useState('');
  const navigate = useNavigate();

  const handleDemoLogin = async () => {
    try {
      setError('');
      setLoading(true);

      // Generate unique user
      const userId = 'user-' + Date.now();
      const userName = name || 'Demo User ' + Math.floor(Math.random() * 1000);
      const userEmail = email || `${userId}@demo.hiddenbites.com`;

      // Create user in database
      const newUser = await usersAPI.createUser({
        email: userEmail,
        name: userName,
        avatar: `https://i.pravatar.cc/150?img=${Math.floor(Math.random() * 100)}`,
        bio: 'Welcome to HiddenBites!',
      });

      console.log('User created:', newUser);

      // Store user info in localStorage
      localStorage.setItem('userId', newUser.id);
      localStorage.setItem('userName', newUser.name);
      localStorage.setItem('userEmail', newUser.email);

      // Redirect to feed
      navigate('/feed');
    } catch (err: any) {
      console.error('Login error:', err);
      if (err.message.includes('already exists')) {
        // User exists, just login
        try {
          const userId = 'user-' + email.split('@')[0];
          localStorage.setItem('userId', userId);
          localStorage.setItem('userName', name || 'User');
          navigate('/feed');
        } catch {
          setError('Login failed. Please try again.');
        }
      } else {
        setError(err.message || 'Failed to login');
      }
    } finally {
      setLoading(false);
    }
  };

  const handleQuickDemo = async () => {
    // Quick demo without form
    const demoNames = [
      'Ahmad Rizki',
      'Siti Nurhaliza',
      'Budi Santoso',
      'Dewi Lestari',
      'Rani Wijaya',
    ];
    const randomName = demoNames[Math.floor(Math.random() * demoNames.length)];
    const userId = 'demo-' + Date.now();

    try {
      setLoading(true);
      await usersAPI.createUser({
        email: `${userId}@demo.com`,
        name: randomName,
        avatar: `https://i.pravatar.cc/150?img=${Math.floor(Math.random() * 100)}`,
        bio: 'Demo user exploring HiddenBites',
      });

      localStorage.setItem('userId', userId);
      localStorage.setItem('userName', randomName);
      navigate('/feed');
    } catch (err) {
      setLoading(false);
      handleQuickDemo(); // Retry with different name
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-orange-50 to-orange-100 flex items-center justify-center py-12 px-4 sm:px-6 lg:px-8">
      <div className="max-w-md w-full space-y-8">
        {/* Header */}
        <div className="text-center">
          <div className="mx-auto h-12 w-12 flex items-center justify-center rounded-full bg-orange-100">
            <span className="text-2xl">🍽️</span>
          </div>
          <h2 className="mt-6 text-3xl font-extrabold text-gray-900">
            Masuk ke HiddenBites
          </h2>
          <p className="mt-2 text-sm text-gray-600">
            Temukan dan bagikan hidden gems kuliner favoritmu
          </p>
        </div>

        {/* Login Card */}
        <div className="bg-white py-8 px-4 shadow-xl rounded-lg sm:px-10">
          <div className="space-y-6">
            {/* Info Message */}
            <div className="bg-blue-50 border border-blue-200 p-4 rounded-lg text-sm text-blue-700">
              <p className="font-medium mb-2">🚀 Demo Mode</p>
              <p>
                Login dengan form di bawah atau langsung coba demo untuk melihat app!
              </p>
            </div>

            {/* Error Message */}
            {error && (
              <div className="bg-red-50 border border-red-200 text-red-600 px-4 py-3 rounded-md text-sm">
                {error}
              </div>
            )}

            {/* Login Form */}
            <div className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Nama (opsional)
                </label>
                <input
                  type="text"
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                  placeholder="Masukkan nama kamu"
                  className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-orange-500 focus:border-transparent"
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Email (opsional)
                </label>
                <input
                  type="email"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  placeholder="email@example.com"
                  className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-orange-500 focus:border-transparent"
                />
              </div>

              <button
                onClick={handleDemoLogin}
                disabled={loading}
                className="w-full bg-orange-600 text-white py-3 rounded-lg hover:bg-orange-700 transition-colors font-medium disabled:opacity-50"
              >
                {loading ? 'Sedang login...' : 'Login'}
              </button>
            </div>

            {/* Divider */}
            <div className="relative">
              <div className="absolute inset-0 flex items-center">
                <div className="w-full border-t border-gray-300"></div>
              </div>
              <div className="relative flex justify-center text-sm">
                <span className="px-2 bg-white text-gray-500">Atau</span>
              </div>
            </div>

            {/* Quick Demo Button */}
            <button
              onClick={handleQuickDemo}
              disabled={loading}
              className="w-full flex justify-center items-center px-4 py-3 border border-gray-300 rounded-md shadow-sm bg-white text-sm font-medium text-gray-700 hover:bg-gray-50 transition-colors disabled:opacity-50"
            >
              {loading ? (
                <>
                  <svg className="animate-spin -ml-1 mr-3 h-5 w-5 text-gray-700" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                    <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                    <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                  </svg>
                  Mempersiapkan...
                </>
              ) : (
                <>
                  <span className="text-xl mr-2">🎬</span>
                  Coba Demo Sekarang
                </>
              )}
            </button>

            {/* Features Preview */}
            <div className="space-y-3">
              <h3 className="text-sm font-medium text-gray-900">Setelah login, kamu bisa:</h3>
              <ul className="space-y-2 text-sm text-gray-600">
                <li className="flex items-center">
                  <span className="text-orange-500 mr-2">✓</span>
                  Bagikan hidden gem kuliner favoritmu
                </li>
                <li className="flex items-center">
                  <span className="text-orange-500 mr-2">✓</span>
                  Temukan tempat makan tersembunyi
                </li>
                <li className="flex items-center">
                  <span className="text-orange-500 mr-2">✓</span>
                  Like dan comment di post
                </li>
                <li className="flex items-center">
                  <span className="text-orange-500 mr-2">✓</span>
                  Lihat profile dan statistik
                </li>
              </ul>
            </div>

            {/* Terms */}
            <div className="text-center text-xs text-gray-500">
              Dengan masuk, kamu setuju dengan{' '}
              <a href="#" className="text-orange-600 hover:text-orange-500">
                Terms of Service
              </a>
              {' '}dan{' '}
              <a href="#" className="text-orange-600 hover:text-orange-500">
                Privacy Policy
              </a>
            </div>
          </div>
        </div>

        {/* Quick Links */}
        <div className="text-center space-y-2">
          <Link
            to="/feed"
            className="block text-orange-600 hover:text-orange-700 font-medium"
          >
            Jelajahi Feed →
          </Link>
          <Link
            to="/profile"
            className="block text-orange-600 hover:text-orange-700 font-medium"
          >
            Lihat Profile →
          </Link>
        </div>
      </div>
    </div>
  );
};

